// Reuses the existing scene, camera, geometry and renderer. Only the H5 shell enables it.
const stellarScene=(()=>{
 const originals=[...planet.children],developed=new T.Group();developed.name='HerstoryDevelopedWorld';originals.forEach(o=>developed.add(o));planet.add(developed);
 const bare=earth.clone();bare.name='HerstoryEmptySphere';bare.geometry=earth.geometry.clone();const pos=bare.geometry.attributes.position;
 for(let i=0;i<pos.count;i++){const x=pos.getX(i),y=pos.getY(i),z=pos.getZ(i),r=2.45/Math.hypot(x,y,z);pos.setXYZ(i,x*r,y*r,z*r);}pos.needsUpdate=true;bare.geometry.computeVertexNormals();bare.material=earth.material.clone();bare.material.vertexColors=false;bare.material.flatShading=false;bare.material.color.set('#b8c18a');planet.add(bare);
 const dollsRoot=new T.Group();dollsRoot.name='FriendFigurines';planet.add(dollsRoot);
 const dolls=new Map(),bodyGeo=new T.CylinderGeometry(.045,.065,.135,7),headGeo=new T.SphereGeometry(.051,8,5),limbGeo=new T.CylinderGeometry(.015,.017,.095,5);
 const skin=new T.MeshStandardMaterial({color:'#e4c4a7',roughness:1}),hair=new T.MeshStandardMaterial({color:'#55493e',roughness:1}),pants=new T.MeshStandardMaterial({color:'#56625c',roughness:1});
 const coats=['#b8896d','#80988d','#c9b274','#b9878d','#748795'].map(color=>new T.MeshStandardMaterial({color,roughness:1}));
 const framingDistance=camera.position.z;let lastLayout='',pixelRatio=renderer.getPixelRatio();let mode='field',stage=0,enabled=false,elapsed=0,selected=null;const used=new Set();
 function hash(s){let n=2166136261;for(const c of s)n=Math.imul(n^c.charCodeAt(0),16777619);return n>>>0;}
 function makeDoll(friend,animate){let slot=0;while(used.has(slot))slot++;used.add(slot);const h=hash(friend.id),angle=slot*2.399963,spread=.11*Math.sqrt(slot+1);const dir=new T.Vector3(Math.cos(angle)*Math.min(.65,spread),Math.sin(angle)*Math.min(.60,spread)+.17,1).normalize();
 const anchor=new T.Group();anchor.name='Friend_'+friend.id;anchor.userData={friendId:friend.id,slot};anchor.position.copy(dir).multiplyScalar(stage===0?2.45:terrain(dir).r+.018);anchor.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),dir);dollsRoot.add(anchor);
 const doll=new T.Group();doll.name='Figurine';anchor.add(doll);const mesh=(g,m,x,y,z)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);doll.add(o);return o;};
 mesh(bodyGeo,coats[h%coats.length],0,.16,0);mesh(headGeo,skin,0,.28,0);const cap=mesh(headGeo,hair,0,.295,-.011);cap.scale.set(1.05,.65,.9);
 for(const sign of [-1,1]){mesh(limbGeo,pants,sign*.025,.05,0);const arm=mesh(limbGeo,coats[h%coats.length],sign*.061,.17,0);arm.rotation.z=sign*.16;}
 doll.scale.setScalar(.9);const item={id:friend.id,anchor,doll,slot,dir,ground:anchor.position.length(),start:animate?elapsed:-10,animated:animate};dolls.set(friend.id,item);return item;
 }
 function applyFriends(friends,{animate=false}={}){const ids=new Set(friends.map(f=>f.id));for(const [id,d]of dolls)if(!ids.has(id)){dollsRoot.remove(d.anchor);used.delete(d.slot);dolls.delete(id);}let created=0;for(const f of friends){if(!dolls.has(f.id)){makeDoll(f,animate);created++;}}return created;}
 function setStage(value){stage=Math.max(0,Math.min(14,Math.floor(value)));developed.visible=stage>0;bare.visible=stage===0;window.herstoryWorld.setStage(Math.max(1,stage));for(const d of dolls.values()){d.ground=stage===0?2.45:terrain(d.dir).r+.018;}}
 function applyGrowth(growth){window.herstoryWorld.setStage(14);assetRegistry.apply(growth.unitIds,growth.modelVersion);stage=growth.unitIds.length?1:0;developed.visible=stage>0;bare.visible=!earth.visible;for(const d of dolls.values())d.ground=bare.visible?2.45:terrain(d.dir).r+.018;}
 function setMode(value){mode=value;enabled=true;scene.background=value==='field'||value==='friends'?null:new T.Color('#f5f5e9');renderer.setClearColor('#0C1210',0);scene.fog=null;layout();}
 function layout(){if(!enabled)return;const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;const key=w+':'+h+':'+mode;if(key===lastLayout)return;lastLayout=key;const targetRatio=Math.min(devicePixelRatio,w<800?(mode==='field'?1.25:1.5):1.75);if(pixelRatio!==targetRatio){pixelRatio=targetRatio;renderer.setPixelRatio(pixelRatio);}const diameter=Math.min(w,h)*(mode==='mine'?.71:.39);const frustum=2*Math.tan(T.MathUtils.degToRad(camera.fov/2))*framingDistance;planet.scale.setScalar(diameter/h*frustum/4.9);planet.position.set(0,0,0);}
 function tick(dt){if(!enabled||mode==='friends')return;elapsed+=Math.min(dt,.05);layout();for(const d of dolls.values()){const u=reduced?1:Math.max(0,Math.min(1,(elapsed-d.start)/1.8));const lift=(1-u)*(1-u)*1.6;d.anchor.position.copy(d.dir).multiplyScalar(d.ground+lift);d.doll.rotation.y=u<1?Math.sin(u*Math.PI*2)*.15:0;}}
 function focusFriend(id){const d=dolls.get(id);if(!d)return;selected=id;goal=new T.Quaternion().setFromUnitVectors(d.dir,new T.Vector3(0,.10,1).normalize());}

 const backgroundCanvas=document.createElement('canvas');backgroundCanvas.width=backgroundCanvas.height=512;const bg=backgroundCanvas.getContext('2d');bg.fillStyle='#44414F';bg.fillRect(0,0,512,512);const halo=bg.createRadialGradient(256,250,0,256,250,285);halo.addColorStop(0,'rgba(87,81,96,.22)');halo.addColorStop(1,'rgba(87,81,96,0)');bg.fillStyle=halo;bg.fillRect(0,0,512,512);const universeBackground=new T.CanvasTexture(backgroundCanvas);universeBackground.colorSpace=T.SRGBColorSpace;
 const schemes=Object.fromEntries(Object.entries(window.HerstoryPlanetPalettes).map(([id,p])=>[id,[p[1],'#789A46']]));let palette='green';const originalColors=earth.geometry.attributes.color.array.slice(),originalBare=bare.material.color.clone(),foliage=[];let treeIndex=0;developed.traverse(group=>{if(!group.userData.planetTree||treeIndex++%2)return;group.traverse(m=>{if(!m.isMesh||!m.material?.color)return;const c=m.material.color;if(c.g>c.r*1.06&&c.g>c.b*1.12){const original=m.material;m.material=original.clone();foliage.push({mesh:m,color:original.color.clone()});}});});
 function setPalette(id){if(!(id in schemes))return false;palette=id;const colors=earth.geometry.attributes.color;colors.array.set(originalColors);bare.material.color.copy(originalBare);foliage.forEach(f=>f.mesh.material.color.copy(f.color));const scheme=schemes[id];if(scheme){const position=earth.geometry.attributes.position,base=new T.Color('#a8b67b'),rock=new T.Color('#999382'),target=new T.Color(scheme[0]),v=new T.Vector3(),old=new T.Color(),ref=new T.Color(),next=new T.Color();for(let i=0;i<colors.count;i++){v.fromBufferAttribute(position,i).normalize();const mix=T.MathUtils.smoothstep(v.dot(window.planetDemo.biomes.volcano.dir),.78,.96);ref.copy(base).lerp(rock,mix);old.fromBufferAttribute(colors,i);const variation=T.MathUtils.clamp((old.r+old.g+old.b)/(ref.r+ref.g+ref.b),.92,1.08);next.copy(target).lerp(rock,mix).multiplyScalar(variation);colors.setXYZ(i,next.r,next.g,next.b);}bare.material.color.set(scheme[0]);foliage.forEach(f=>f.mesh.material.color.set(scheme[1]));}colors.needsUpdate=true;return true;}
 function capturePhoto(options={}){const width=options.width||1080,height=options.height||1920;let backdrop=null;const size=renderer.getSize(new T.Vector2()),pixelRatio=renderer.getPixelRatio(),background=scene.background,scale=planet.scale.clone(),position=planet.position.clone();try{const photoCamera=camera.clone();photoCamera.aspect=width/height;photoCamera.position.set(0,0,(options.planetFraction?2.45/options.planetFraction:3.63)/(Math.tan(T.MathUtils.degToRad(photoCamera.fov/2))*photoCamera.aspect));photoCamera.lookAt(0,0,0);photoCamera.updateProjectionMatrix();planet.scale.setScalar(1);planet.position.set(0,0,0);if(options.background){backdrop=new T.CanvasTexture(options.background);backdrop.colorSpace=T.SRGBColorSpace;scene.background=backdrop;}else scene.background=new T.Color('#f5f5e9');renderer.setPixelRatio(1);renderer.setSize(width,height,false);renderer.render(scene,photoCamera);const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(renderer.domElement,0,0);return canvas;}finally{planet.scale.copy(scale);planet.position.copy(position);scene.background=background;backdrop?.dispose();renderer.setPixelRatio(pixelRatio);renderer.setSize(size.x,size.y,false);camera.updateProjectionMatrix();renderer.render(scene,camera);}}
 document.querySelector('#reset').onclick=()=>{distance=framingDistance;window.herstoryWorld.focus('all');};
 addEventListener('resize',()=>{lastLayout='';layout();});
 const api={setPalette,capturePhoto,setMode,setStage,applyGrowth,applyFriends,focusFriend,tick,audit(){return {mode,stage,palette,bodyColor:bare.material.color.getHexString(),cameraDistance:camera.position.z,worldScale:planet.scale.x,pixelRatio:renderer.getPixelRatio(),friendIds:[...dolls.keys()],dolls:dolls.size,selected,falling:[...dolls.values()].filter(d=>elapsed-d.start<1.8).length,originalWorldChildren:originals.length};}};return api;
})();
window.stellarScene=stellarScene;
